union all
select
    'US-' || state_fips || county_fips as place_key,
    arg_max(county_name, year) as place_name,
    'county' as place_level,
    'US-' || state_fips as parent_key,
    state_fips || county_fips as fips,
    cast(null as varchar) as postal
from {{ ref('int_census_county_pop') }}
where sumlev = '050' and state_fips is not null and county_fips is not null
group by state_fips, county_fips
